/*
 * Interpreter Implementation
 *
 * This file contains the core implementation of the A++ interpreter, responsible for
 * executing the Abstract Syntax Tree (AST) generated by the parser.
 *
 * Key features:
 * - Variable management and type handling
 * - Expression evaluation
 * - Control flow execution (if/else, loops)
 * - Function calls and string operations
 * - Type casting and conversions
 * - Built-in functions (print, input, etc.)
 *
 * Original Author: Paul Kabulu
 * Created: August 2024
 *
 * Edited by: Paul Kabulu - January 2025 - Integrated array interpretation and element accessing from array.c and array_ops.c
 *
 *
 * File: src/interpreter/interpreter.c
 */

#include <stdarg.h>
#include "interpreter.h"
#include "common/types.h"
#include <stdbool.h>
#include "array.h"
#include "array_ops.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>
#include <time.h>

// This defines the maximum number of variables our program can handle
#define MAX_VARIABLES 100
#define MAX_FUNCTIONS 100

// This structure represents a variable in our program
typedef struct
{
    char *name;        // The name of the variable
    VariableType type; // The type of the variable (int or string)
    bool is_fixed;     // Whether the variable is fixed (constant)
    union
    {
        int int_value; // If it's an int, store the value here
        double float_value;
        char *string_value;
        bool bool_value;
        char char_value;
        ArrayValue *array_value;
    } value;
} Variable;

// Function definition structure
typedef struct
{
    char *name;
    char *return_type;
    ASTNode *parameters;
    ASTNode *body;
} Function;

// Function declarations
static int evaluate_expression(ASTNode *node);
static bool evaluate_bool_expression(ASTNode *node);
static double evaluate_float_expression(ASTNode *node);
static char *evaluate_string_expression(ASTNode *node);
static VariableType get_type_from_string(const char *type_str);
static Function *find_function(const char *name);
static char *execute_function(const char *name, ASTNode *arguments);
static void set_variable(const char *name, VariableType type, void *value);
static Variable *get_variable(const char *name);

void *interpret_array_literal(ASTNode *node);
void *interpret_array_access(ASTNode *node, ArrayValue *array);
void *interpret_array_method_call(ASTNode *node, ArrayValue *array);
char *extract_array_type(const char *var_type);

static Function *find_function(const char *name);
static char *execute_function(const char *name, ASTNode *arguments);
static void set_variable(const char *name, VariableType type, void *value);
static Variable *get_variable(const char *name);
static char *execute_function_body(const char *return_type, ASTNode *body);
static char *evaluate_input(const char *prompt);
static void handle_type_cast(ASTNode *node);
static bool evaluate_comparison(ASTNode *node);
void *interpret_expression(ASTNode *node);
static int get_string_length(const char *str);
static void register_builtin_functions(void);
static void handle_assignment(ASTNode *node);

// Global variables
static Function functions[MAX_FUNCTIONS];
static int function_count = 0;
static Variable variables[MAX_VARIABLES];
static int variable_count = 0;
static bool builtins_registered = false;

static void DEBUG_LOG(const char *format, ...)
{
    va_list args;
    va_start(args, format);
    printf("[DEBUG] ");
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

// Helper function to convert type string to VariableType
static VariableType get_type_from_string(const char *type_str)
{
    if (strcmp(type_str, "int") == 0)
    {
        return INT_TYPE;
    }
    else if (strcmp(type_str, "float") == 0)
    {
        return FLOAT_TYPE;
    }
    else if (strcmp(type_str, "string") == 0)
    {
        return STRING_TYPE;
    }
    else if (strcmp(type_str, "boolean") == 0)
    {
        return BOOL_TYPE;
    }
    else if (strcmp(type_str, "char") == 0)
    {
        return CHAR_TYPE;
    }
    return INT_TYPE; // Default to INT_TYPE
}

static VariableType get_function_return_type(const char *return_type_str)
{
    if (strcmp(return_type_str, "int") == 0)
    {
        return INT_TYPE;
    }
    else if (strcmp(return_type_str, "float") == 0)
    {
        return FLOAT_TYPE;
    }
    else if (strcmp(return_type_str, "string") == 0)
    {
        return STRING_TYPE;
    }
    else if (strcmp(return_type_str, "boolean") == 0)
    {
        return BOOL_TYPE;
    }
    else if (strcmp(return_type_str, "char") == 0)
    {
        return CHAR_TYPE;
    }
    return INT_TYPE; // Default
}

// Register a function definition
void register_function(char *name, char *return_type, ASTNode *parameters, ASTNode *body)
{
    if (function_count >= MAX_FUNCTIONS)
    {
        printf("Error: Maximum number of functions reached\n");
        return;
    }

    // Check if function already exists
    for (int i = 0; i < function_count; i++)
    {
        if (strcmp(functions[i].name, name) == 0)
        {
            printf("Error: Function '%s' already defined\n", name);
            return;
        }
    }

    functions[function_count].name = strdup(name);
    functions[function_count].return_type = strdup(return_type);
    functions[function_count].parameters = parameters;
    functions[function_count].body = body;
    function_count++;
}

// Find a function by name
Function *find_function(const char *name)
{
    for (int i = 0; i < function_count; i++)
    {
        if (strcmp(functions[i].name, name) == 0)
        {
            return &functions[i];
        }
    }
    return NULL;
}

// Execute a function and return its result as a string
char *execute_function(const char *name, ASTNode *arguments)
{

    // Make sure built-ins are registered
    register_builtin_functions();

    // Handle type cast nodes specially
    if (arguments && arguments->type == NODE_TYPE_CAST)
    {

        if (!arguments->target_type)
        {
            printf("[ERROR] Target type is NULL\n");
            return NULL;
        }

        if (strcmp(arguments->target_type, "float") == 0)
        {

            if (!arguments->left)
            {
                printf("[ERROR] No expression to convert (left node is NULL)\n");
                return NULL;
            }

            if (arguments->left->type == NODE_STRING_LITERAL)
            {
                double val = atof(arguments->left->value);
                char result[32];
                snprintf(result, sizeof(result), "%g", val);
                return strdup(result);
            }
            else if (arguments->left->type == NODE_INT_LITERAL)
            {
                double val = (double)atoi(arguments->left->value);
                char result[32];
                snprintf(result, sizeof(result), "%g", val);
                return strdup(result);
            }
            else if (arguments->left->type == NODE_LITERAL)
            {
                Variable *var = get_variable(arguments->left->value);
                if (var)
                {
                    double val = 0.0;
                    if (var->type == INT_TYPE)
                    {
                        val = (double)var->value.int_value;
                    }
                    else if (var->type == STRING_TYPE)
                    {
                        val = atof(var->value.string_value);
                    }
                    else if (var->type == FLOAT_TYPE)
                    {
                        val = var->value.float_value;
                    }
                    char result[32];
                    snprintf(result, sizeof(result), "%g", val);
                    return strdup(result);
                }
                else
                {
                    printf("[ERROR] Variable not found: %s\n", arguments->left->value);
                }
            }
            else
            {
                printf("[ERROR] Unsupported node type for float conversion: %d\n", arguments->left->type);
            }
        }
        else
        {
            printf("[ERROR] Unsupported cast type: %s\n", arguments->target_type);
        }
        return NULL;
    }

    if (strcmp(name, "length") == 0)
    {
        if (!arguments)
        {
            printf("Error: length() requires an argument\n");
            return strdup("0");
        }

        // Handle array length
        if (arguments->type == NODE_LITERAL)
        {
            Variable *var = get_variable(arguments->value);
            if (var && var->type == ARRAY_TYPE && var->value.array_value)
            {
                char result[32];
                snprintf(result, sizeof(result), "%zu", var->value.array_value->length);
                return strdup(result);
            }
        }

        // Handle string length (existing functionality)
        char *str_value = NULL;
        if (arguments->type == NODE_STRING_LITERAL)
        {
            str_value = arguments->value;
        }
        else if (arguments->type == NODE_LITERAL)
        {
            Variable *var = get_variable(arguments->value);
            if (var && var->type == STRING_TYPE)
            {
                str_value = var->value.string_value;
            }
        }
        else if (arguments->type == NODE_FUNCTION_CALL)
        {
            str_value = execute_function(arguments->function_name, arguments->arguments);
        }

        if (str_value)
        {
            int length = strlen(str_value);
            char result[32];
            snprintf(result, sizeof(result), "%d", length);

            if (arguments->type == NODE_FUNCTION_CALL)
            {
                free(str_value);
            }

            return strdup(result);
        }

        printf("Error: Argument to length() must be a string or array\n");
        return strdup("0");
    }

    else if (strcmp(name, "date") == 0)
    {
        time_t t = time(NULL);
        struct tm *tm_info = localtime(&t);
        char result[64] = {0};

        if (!arguments)
        {
            // Default format: YYYY-MM-DD
            strftime(result, sizeof(result), "%Y-%m-%d", tm_info);
        }
        else
        {
            // Parse arguments and build custom format
            char format[32] = {0};
            char *ptr = format;
            ASTNode *current = arguments;
            bool has_year = false, has_month = false, has_day = false;

            while (current)
            {
                char *arg = evaluate_string_expression(current);
                if (!arg)
                {
                    printf("Error: Invalid argument for date()\n");
                    return strdup("");
                }

                if (strcmp(arg, "Y") == 0 && !has_year)
                {
                    if (ptr != format)
                        *ptr++ = '-';
                    strcpy(ptr, "%Y");
                    ptr += 2;
                    has_year = true;
                }
                else if (strcmp(arg, "M") == 0 && !has_month)
                {
                    if (ptr != format)
                        *ptr++ = '-';
                    strcpy(ptr, "%m");
                    ptr += 2;
                    has_month = true;
                }
                else if (strcmp(arg, "D") == 0 && !has_day)
                {
                    if (ptr != format)
                        *ptr++ = '-';
                    strcpy(ptr, "%d");
                    ptr += 2;
                    has_day = true;
                }

                free(arg);
                current = current->next;
            }

            if (format[0] == 0)
            {
                // If no valid format specified, use default
                strftime(result, sizeof(result), "%Y-%m-%d", tm_info);
            }
            else
            {
                strftime(result, sizeof(result), format, tm_info);
            }
        }

        return strdup(result);
    }
    else if (strcmp(name, "time") == 0)
    {
        time_t t = time(NULL);
        struct tm *tm_info = localtime(&t);
        char result[64];

        // Format: HH:MM:SS
        strftime(result, sizeof(result), "%H:%M:%S", tm_info);
        return strdup(result);
    }
    else if (strcmp(name, "now") == 0)
    {
        time_t t = time(NULL);
        struct tm *tm_info = localtime(&t);
        char result[64];

        // Format: YYYY-MM-DD HH:MM:SS
        strftime(result, sizeof(result), "%Y-%m-%d %H:%M:%S", tm_info);
        return strdup(result);
    }

    else if (strcmp(name, "charAt") == 0)
    {
        // Get the string argument
        if (!arguments)
        {
            printf("Error: charAt() requires two arguments: string and index\n");
            return strdup("");
        }

        // Get the string value
        char *str_value = NULL;
        if (arguments->type == NODE_STRING_LITERAL)
        {
            str_value = arguments->value;
        }
        else if (arguments->type == NODE_LITERAL)
        {
            Variable *var = get_variable(arguments->value);
            if (var && var->type == STRING_TYPE)
            {
                str_value = var->value.string_value;
            }
        }

        // Get the index argument
        ASTNode *index_arg = arguments->next;
        if (!index_arg)
        {
            printf("Error: charAt() requires an index argument\n");
            return strdup("");
        }

        int index = evaluate_expression(index_arg);

        // Validate string and index
        if (!str_value)
        {
            printf("Error: First argument to charAt() must be a string\n");
            return strdup("");
        }

        size_t str_len = strlen(str_value);
        if (index < 0 || (size_t)index >= str_len)
        {
            printf("Error: String index %d out of range (0-%zu)\n", index, str_len - 1);
            return strdup("");
        }

        // Create a single character string result
        char *result = malloc(2);
        result[0] = str_value[index];
        result[1] = '\0';
        return result;
    }

    // Handle substring function
    if (strcmp(name, "substring") == 0)
    {
        if (!arguments || !arguments->next || !arguments->next->next)
        {
            printf("Error: substring() requires three arguments\n");
            return strdup("");
        }

        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: First argument to substring() must be a string\n");
            return strdup("");
        }

        int start = evaluate_expression(arguments->next);
        int end = evaluate_expression(arguments->next->next);
        size_t str_len = strlen(str_value);

        if (start < 0 || end < 0 || (size_t)start >= str_len || (size_t)end > str_len || start > end)
        {
            printf("Error: Invalid substring indices\n");
            free(str_value);
            return strdup("");
        }

        size_t len = end - start;
        char *result = malloc(len + 1);
        strncpy(result, str_value + start, len);
        result[len] = '\0';

        free(str_value);
        return result;
    }

    // Handle concat function
    if (strcmp(name, "concat") == 0)
    {
        if (!arguments || !arguments->next)
        {
            printf("Error: concat() requires two arguments\n");
            return strdup("");
        }

        char *str1 = evaluate_string_expression(arguments);
        char *str2 = evaluate_string_expression(arguments->next);

        if (!str1 || !str2)
        {
            printf("Error: Both arguments to concat() must be strings\n");
            free(str1);
            free(str2);
            return strdup("");
        }

        size_t len = strlen(str1) + strlen(str2);
        char *result = malloc(len + 1);
        strcpy(result, str1);
        strcat(result, str2);

        free(str1);
        free(str2);
        return result;
    }

    // Handle replace function
    if (strcmp(name, "replace") == 0)
    {
        if (!arguments || !arguments->next || !arguments->next->next)
        {
            printf("Error: replace() requires three arguments\n");
            return strdup("");
        }

        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: First argument to replace() must be a string\n");
            return strdup("");
        }

        int index = evaluate_expression(arguments->next);
        char *new_char = evaluate_string_expression(arguments->next->next);

        if (!new_char || strlen(new_char) != 1)
        {
            printf("Error: Third argument to replace() must be a single character\n");
            free(str_value);
            free(new_char);
            return strdup("");
        }

        size_t str_len = strlen(str_value);
        if (index < 0 || (size_t)index >= str_len)
        {
            printf("Error: String index %d out of range (0-%zu)\n", index, str_len - 1);
            free(str_value);
            free(new_char);
            return strdup("");
        }

        char *result = strdup(str_value);
        result[index] = new_char[0];

        free(str_value);
        free(new_char);
        return result;
    }

    else if (strcmp(name, "indexOf") == 0)
    {
        if (!arguments || !arguments->next)
        {
            printf("Error: indexOf() requires two arguments: string and character\n");
            return strdup("-1");
        }

        // Get the string argument
        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: First argument to indexOf() must be a string\n");
            return strdup("-1");
        }

        // Get the character to search for
        char *char_value = evaluate_string_expression(arguments->next);
        if (!char_value || strlen(char_value) != 1)
        {
            printf("Error: Second argument to indexOf() must be a single character\n");
            free(str_value);
            free(char_value);
            return strdup("-1");
        }

        // Search for the character
        char *pos = strchr(str_value, char_value[0]);
        int index = (pos != NULL) ? (int)(pos - str_value) : -1;

        // Clean up
        free(str_value);
        free(char_value);

        // Return result as string
        char result[32];
        snprintf(result, sizeof(result), "%d", index);
        return strdup(result);
    }

    else if (strcmp(name, "toLowerCase") == 0)
    {
        if (!arguments)
        {
            printf("Error: toLowerCase() requires a string argument\n");
            return strdup("");
        }

        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: Argument to toLowerCase() must be a string\n");
            return strdup("");
        }

        // Convert string to lowercase
        for (char *p = str_value; *p; p++)
        {
            *p = tolower((unsigned char)*p);
        }

        return str_value; // Return the modified string
    }
    else if (strcmp(name, "toUpperCase") == 0)
    {
        if (!arguments)
        {
            printf("Error: toUpperCase() requires a string argument\n");
            return strdup("");
        }

        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: Argument to toUpperCase() must be a string\n");
            return strdup("");
        }

        // Convert string to uppercase
        for (char *p = str_value; *p; p++)
        {
            *p = toupper((unsigned char)*p);
        }

        return str_value; // Return the modified string
    }

    else if (strcmp(name, "reverse") == 0)
    {
        if (!arguments)
        {
            printf("Error: reverse() requires a string argument\n");
            return strdup("");
        }

        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: Argument to reverse() must be a string\n");
            return strdup("");
        }

        // Get string length
        size_t len = strlen(str_value);

        // Reverse the string in place
        for (size_t i = 0; i < len / 2; i++)
        {
            char temp = str_value[i];
            str_value[i] = str_value[len - 1 - i];
            str_value[len - 1 - i] = temp;
        }

        return str_value;
    }
    else if (strcmp(name, "trim") == 0)
    {
        if (!arguments)
        {
            printf("Error: trim() requires a string argument\n");
            return strdup("");
        }

        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: Argument to trim() must be a string\n");
            return strdup("");
        }

        // Find first non-whitespace character
        char *start = str_value;
        while (*start && isspace((unsigned char)*start))
        {
            start++;
        }

        // Find last non-whitespace character
        char *end = str_value + strlen(str_value);
        while (end > start && isspace((unsigned char)*(end - 1)))
        {
            end--;
        }

        // Calculate new length
        size_t new_len = end - start;

        // Create new trimmed string
        char *result = malloc(new_len + 1);
        if (result)
        {
            strncpy(result, start, new_len);
            result[new_len] = '\0';
        }

        free(str_value);
        return result ? result : strdup("");
    }

    else if (strcmp(name, "repeat") == 0)
    {
        if (!arguments || !arguments->next)
        {
            printf("Error: repeat() requires at least two arguments: string and count\n");
            return strdup("");
        }

        // Get the string to repeat
        char *str_value = evaluate_string_expression(arguments);
        if (!str_value)
        {
            printf("Error: First argument to repeat() must be a string\n");
            return strdup("");
        }

        // Get the number of repetitions
        int count = evaluate_expression(arguments->next);
        if (count < 0)
        {
            printf("Error: Repeat count must be non-negative\n");
            free(str_value);
            return strdup("");
        }

        // Get the optional delimiter (default to empty string)
        char *delimiter = "";
        if (arguments->next->next)
        {
            delimiter = evaluate_string_expression(arguments->next->next);
            if (!delimiter)
            {
                printf("Error: Third argument to repeat() must be a string\n");
                free(str_value);
                return strdup("");
            }
        }

        // Calculate the total length needed
        size_t str_len = strlen(str_value);
        size_t delim_len = strlen(delimiter);
        size_t total_len = (str_len * count) + (delim_len * (count - 1));

        // Allocate memory for the result
        char *result = malloc(total_len + 1);
        if (!result)
        {
            printf("Error: Memory allocation failed\n");
            free(str_value);
            if (arguments->next->next)
                free(delimiter);
            return strdup("");
        }

        // Build the repeated string
        char *ptr = result;
        for (int i = 0; i < count; i++)
        {
            // Copy the string
            strcpy(ptr, str_value);
            ptr += str_len;

            // Add delimiter if not the last iteration
            if (i < count - 1 && delim_len > 0)
            {
                strcpy(ptr, delimiter);
                ptr += delim_len;
            }
        }

        // Clean up
        free(str_value);
        if (arguments->next->next)
            free(delimiter);

        return result;
    }

    else if (strcmp(name, "round") == 0)
    {
        if (!arguments)
        {
            printf("Error: round() requires at least one argument\n");
            return strdup("0");
        }

        // Get the number to round
        double number;
        if (arguments->type == NODE_INT_LITERAL)
        {
            number = (double)evaluate_expression(arguments);
        }
        else
        {
            number = evaluate_float_expression(arguments);
        }

        // Get the optional direction (U for up, D for down)
        char *direction = NULL;
        if (arguments->next)
        {
            direction = evaluate_string_expression(arguments->next);
            if (!direction)
            {
                printf("Error: Second argument to round() must be 'U' or 'D'\n");
                return strdup("0");
            }
        }

        int rounded;
        if (direction)
        {
            if (strcmp(direction, "U") == 0)
            {
                rounded = (int)ceil(number);
            }
            else if (strcmp(direction, "D") == 0)
            {
                rounded = (int)floor(number);
            }
            else
            {
                printf("Error: Round direction must be 'U' or 'D'\n");
                free(direction);
                return strdup("0");
            }
            free(direction);
        }
        else
        {
            // Default rounding behavior
            rounded = (int)(number + (number >= 0 ? 0.5 : -0.5));
        }

        char result[32];
        snprintf(result, sizeof(result), "%d", rounded);
        return strdup(result);
    }
    else if (strcmp(name, "abs") == 0)
    {
        if (!arguments)
        {
            printf("Error: abs() requires one argument\n");
            return strdup("0");
        }

        // Handle both integer and float inputs
        if (arguments->type == NODE_INT_LITERAL)
        {
            int value = evaluate_expression(arguments);
            int abs_value = value < 0 ? -value : value;
            char result[32];
            snprintf(result, sizeof(result), "%d", abs_value);
            return strdup(result);
        }
        else
        {
            double value = evaluate_float_expression(arguments);
            double abs_value = fabs(value);
            char result[32];
            snprintf(result, sizeof(result), "%g", abs_value);
            return strdup(result);
        }
    }

    else if (strcmp(name, "toPrecision") == 0)
    {
        if (!arguments || !arguments->next)
        {
            printf("Error: toPrecision() requires two arguments: number and decimal places\n");
            return strdup("0");
        }

        // Get the number
        double number = evaluate_float_expression(arguments);

        // Get the number of decimal places
        int decimals = evaluate_expression(arguments->next);
        if (decimals < 0)
        {
            printf("Error: Number of decimal places cannot be negative\n");
            return strdup("0");
        }

        // Calculate the rounding factor
        double factor = pow(10, decimals);

        // Round the number using the factor
        double rounded = round(number * factor) / factor;

        // Create format string for specified precision
        char format[32];
        snprintf(format, sizeof(format), "%%.%df", decimals);

        // Format the number with specified precision
        char result[64];
        snprintf(result, sizeof(result), format, rounded);
        return strdup(result);
    }
    else if (strcmp(name, "min") == 0 || strcmp(name, "max") == 0)
    {
        if (!arguments)
        {
            printf("Error: %s() requires at least one argument\n", name);
            return strdup("0");
        }

        bool is_max = (strcmp(name, "max") == 0);
        double result = evaluate_float_expression(arguments);
        ASTNode *current = arguments->next;

        // Iterate through all arguments
        while (current)
        {
            double value = evaluate_float_expression(current);
            if (is_max)
            {
                if (value > result)
                    result = value;
            }
            else
            {
                if (value < result)
                    result = value;
            }
            current = current->next;
        }

        // Check if result is a whole number
        if (result == (int)result)
        {
            char str_result[32];
            snprintf(str_result, sizeof(str_result), "%d", (int)result);
            return strdup(str_result);
        }
        else
        {
            char str_result[32];
            snprintf(str_result, sizeof(str_result), "%g", result);
            return strdup(str_result);
        }
    }

    else if (strcmp(name, "sin") == 0)
    {
        if (!arguments)
        {
            printf("Error: sin() requires one argument\n");
            return strdup("0");
        }
        double angle = evaluate_float_expression(arguments);
        double result = sin(angle);
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }
    else if (strcmp(name, "cos") == 0)
    {
        if (!arguments)
        {
            printf("Error: cos() requires one argument\n");
            return strdup("0");
        }
        double angle = evaluate_float_expression(arguments);
        double result = cos(angle);
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }
    else if (strcmp(name, "tan") == 0)
    {
        if (!arguments)
        {
            printf("Error: tan() requires one argument\n");
            return strdup("0");
        }
        double angle = evaluate_float_expression(arguments);
        double result = tan(angle);
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }
    else if (strcmp(name, "asin") == 0)
    {
        if (!arguments)
        {
            printf("Error: asin() requires one argument\n");
            return strdup("0");
        }
        double value = evaluate_float_expression(arguments);
        if (value < -1 || value > 1)
        {
            printf("Error: asin() argument must be between -1 and 1\n");
            return strdup("0");
        }
        double result = asin(value);
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }
    else if (strcmp(name, "acos") == 0)
    {
        if (!arguments)
        {
            printf("Error: acos() requires one argument\n");
            return strdup("0");
        }
        double value = evaluate_float_expression(arguments);
        if (value < -1 || value > 1)
        {
            printf("Error: acos() argument must be between -1 and 1\n");
            return strdup("0");
        }
        double result = acos(value);
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }
    else if (strcmp(name, "atan") == 0)
    {
        if (!arguments)
        {
            printf("Error: atan() requires one argument\n");
            return strdup("0");
        }
        double value = evaluate_float_expression(arguments);
        double result = atan(value);
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }

    else if (strcmp(name, "sqrt") == 0)
    {
        if (!arguments)
        {
            printf("Error: sqrt() requires one argument\n");
            return strdup("0");
        }

        double number = evaluate_float_expression(arguments);
        if (number < 0)
        {
            printf("Error: Cannot calculate square root of negative number\n");
            return strdup("0");
        }

        double result = sqrt(number);
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }
    else if (strcmp(name, "cbrt") == 0)
    {
        if (!arguments)
        {
            printf("Error: cbrt() requires one argument\n");
            return strdup("0");
        }

        double number = evaluate_float_expression(arguments);
        double result = cbrt(number); // cbrt handles negative numbers correctly
        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }
    else if (strcmp(name, "root") == 0)
    {
        if (!arguments || !arguments->next)
        {
            printf("Error: root() requires two arguments: number and nth root\n");
            return strdup("0");
        }

        double number = evaluate_float_expression(arguments);
        double n = evaluate_float_expression(arguments->next);

        // Check for valid input
        if (n == 0)
        {
            printf("Error: Root index cannot be zero\n");
            return strdup("0");
        }

        // Handle even roots of negative numbers
        if (number < 0 && fmod(n, 2) == 0)
        {
            printf("Error: Cannot calculate even root of negative number\n");
            return strdup("0");
        }

        // Calculate nth root using power function
        double result;
        if (number < 0)
        {
            // For negative numbers, calculate the root of absolute value
            // and then negate the result
            result = -pow(-number, 1.0 / n);
        }
        else
        {
            result = pow(number, 1.0 / n);
        }

        char str_result[32];
        snprintf(str_result, sizeof(str_result), "%.10g", result);
        return strdup(str_result);
    }

    Function *func = find_function(name);
    if (!func)
    {
        printf("Error: Function '%s' not found\n", name);
        return NULL;
    }

    // Save current variable count to restore after function execution
    int saved_var_count = variable_count;

    // Create a new scope for function parameters
    ASTNode *param = func->parameters;
    ASTNode *arg = arguments;

    while (param && arg)
    {
        // Evaluate argument
        void *value = NULL;
        int int_val;
        double float_val;
        bool bool_val;
        char char_val;
        char *str_val;

        if (strcmp(param->var_type, "int") == 0)
        {
            int_val = evaluate_expression(arg);
            value = &int_val;
        }
        else if (strcmp(param->var_type, "float") == 0)
        {
            float_val = evaluate_float_expression(arg);
            value = &float_val;
        }
        else if (strcmp(param->var_type, "string") == 0)
        {
            str_val = evaluate_string_expression(arg);
            value = str_val;
        }
        else if (strcmp(param->var_type, "boolean") == 0)
        {
            bool_val = evaluate_bool_expression(arg);
            value = &bool_val;
        }
        else if (strcmp(param->var_type, "char") == 0)
        {
            char_val = (char)evaluate_expression(arg);
            value = &char_val;
        }

        // Set parameter value
        if (value)
        {
            set_variable(param->var_name, get_type_from_string(param->var_type), value);
            if (strcmp(param->var_type, "string") == 0)
            {
                free(str_val);
            }
        }

        param = param->next;
        arg = arg->next;
    }

    // Execute function body
    ASTNode *current = func->body;
    char *result = NULL;

    while (current)
    {
        if (current->type == NODE_YIELD_STATEMENT)
        {
            if (!current->left)
            {
                return strdup("");
            }

            // Handle yield statement based on return type
            if (strcmp(func->return_type, "int") == 0)
            {
                int val = evaluate_expression(current->left);
                char buf[32];
                snprintf(buf, sizeof(buf), "%d", val);
                result = strdup(buf);
            }
            else if (strcmp(func->return_type, "float") == 0)
            {
                double val = evaluate_float_expression(current->left);
                char buf[32];
                if (val == (int)val)
                {
                    snprintf(buf, sizeof(buf), "%.1f", val); // Force .0 for whole numbers
                }
                else
                {
                    snprintf(buf, sizeof(buf), "%g", val); // Use original precision for decimals
                }
                result = strdup(buf);
            }
            else if (strcmp(func->return_type, "string") == 0)
            {
                if (current->left->type == NODE_STRING_LITERAL)
                {
                    result = strdup(current->left->value);
                }
                else
                {
                    result = evaluate_string_expression(current->left);
                }
                if (!result)
                {
                    result = strdup("");
                }
            }
            else if (strcmp(func->return_type, "boolean") == 0)
            {
                bool val = evaluate_bool_expression(current->left);
                result = strdup(val ? "yup" : "nope");
            }
            else if (strcmp(func->return_type, "char") == 0)
            {
                char val = (char)evaluate_expression(current->left);
                result = (char *)malloc(2);
                result[0] = val;
                result[1] = '\0';
            }
            break;
        }
        else if (current->type == NODE_IF)
        {
            bool condition = evaluate_bool_expression(current->left);
            if (condition)
            {
                char *if_result = execute_function_body(func->return_type, current->right);
                if (if_result)
                {
                    result = if_result;
                    break;
                }
            }
            else if (current->else_branch)
            {
                char *else_result = execute_function_body(func->return_type, current->else_branch);
                if (else_result)
                {
                    result = else_result;
                    break;
                }
            }
            current = current->next;
        }
        else
        {
            interpret(current);
            current = current->next;
        }
    }

    // Restore variable count (clean up function scope)
    while (variable_count > saved_var_count)
    {
        variable_count--;
        free(variables[variable_count].name);
        if (variables[variable_count].type == STRING_TYPE)
        {
            free(variables[variable_count].value.string_value);
        }
    }

    if (func->return_type && strcmp(func->return_type, "nothing") == 0)
    {
        // For void functions, just execute the body and return NULL
        return NULL; // Don't execute the body here
    }

    return result;
}

static char *execute_function_body(const char *return_type, ASTNode *body)
{
    ASTNode *current = body;
    char *result = NULL;

    while (current)
    {
        if (current->type == NODE_YIELD_STATEMENT)
        {
            if (!current->left)
            {
                return strdup("");
            }

            // Handle yield statement based on return type
            if (strcmp(return_type, "int") == 0)
            {
                int val = evaluate_expression(current->left);
                char buf[32];
                snprintf(buf, sizeof(buf), "%d", val);
                result = strdup(buf);
            }
            else if (strcmp(return_type, "float") == 0)
            {
                double val = evaluate_float_expression(current->left);
                char buf[32];
                if (val == (int)val)
                {
                    snprintf(buf, sizeof(buf), "%.1f", val); // Force .0 for whole numbers
                }
                else
                {
                    snprintf(buf, sizeof(buf), "%g", val); // Use original precision for decimals
                }
                result = strdup(buf);
            }
            else if (strcmp(return_type, "string") == 0)
            {
                if (current->left->type == NODE_STRING_LITERAL)
                {
                    result = strdup(current->left->value);
                }
                else
                {
                    result = evaluate_string_expression(current->left);
                }
                if (!result)
                {
                    result = strdup("");
                }
            }
            else if (strcmp(return_type, "boolean") == 0)
            {
                bool val = evaluate_bool_expression(current->left);
                result = strdup(val ? "yup" : "nope");
            }
            else if (strcmp(return_type, "char") == 0)
            {
                char val = (char)evaluate_expression(current->left);
                result = (char *)malloc(2);
                result[0] = val;
                result[1] = '\0';
            }
            break;
        }
        else
        {
            interpret(current);
            current = current->next;
        }
    }

    return result;
}

// This function sets the value of a variable
static void set_variable(const char *name, VariableType type, void *value)
{
    // First, we check if the variable already exists
    for (int i = 0; i < variable_count; i++)
    {
        if (strcmp(variables[i].name, name) == 0)
        {
            // If it exists, we update its value
            variables[i].type = type;
            if (type == INT_TYPE)
            {
                // If it's an int, we store the int value
                variables[i].value.int_value = *(int *)value;
            }
            else if (type == STRING_TYPE)
            {
                // If it's a string, we free the old string and store the new one
                free(variables[i].value.string_value);
                variables[i].value.string_value = strdup((char *)value);
            }
            if (type == ARRAY_TYPE)
            {
                variables[i].value.array_value = (ArrayValue *)value;
            }
            else if (type == BOOL_TYPE)
            {
                variables[i].value.bool_value = *(bool *)value;
                }
            else if (type == FLOAT_TYPE)
            {
                variables[i].value.float_value = *(double *)value;
            }
            else if (type == CHAR_TYPE)
            {
                variables[i].value.char_value = *(char *)value;
            }
            return;
        }
    }

    // If the variable doesn't exist, we create a new one
    if (variable_count < MAX_VARIABLES)
    {
        // We store the name of the variable
        variables[variable_count].name = strdup(name);
        variables[variable_count].type = type;
        variables[variable_count].is_fixed = false; // New variables are not fixed by default
        if (type == INT_TYPE)
        {
            // If it's an int, we store the int value
            variables[variable_count].value.int_value = *(int *)value;
        }
        else if (type == ARRAY_TYPE) // Add array handling
        {
            // printf("DEBUG: Setting new array value at %p\n", value);
            variables[variable_count].value.array_value = (ArrayValue *)value;
        }
        else if (type == STRING_TYPE)
        {
            // If it's a string, we store a copy of the string
            variables[variable_count].value.string_value = strdup((char *)value);
        }
        else if (type == BOOL_TYPE)
        {
            variables[variable_count].value.bool_value = *(bool *)value;
        }
        else if (type == FLOAT_TYPE)
        {
            variables[variable_count].value.float_value = *(double *)value;
        }
        else if (type == CHAR_TYPE)
        {
            variables[variable_count].value.char_value = *(char *)value;
        }
        variable_count++;
    }
    else
    {
        // If we've reached the maximum number of variables, we print an error
        printf("Error: Maximum number of variables reached.\n");
    }
}

static bool strtobool(const char *str)
{
    if (str == NULL)
        return false;
    return (strcmp(str, "yup") == 0);
}

// This function gets the value of a variable
static Variable *get_variable(const char *name)
{
    // We loop through all variables
    for (int i = 0; i < variable_count; i++)
    {
        // If we find a variable with the given name, we return it
        if (strcmp(variables[i].name, name) == 0)
        {
            return &variables[i];
        }
    }

    // If we didn't find the variable, we return NULL
    return NULL;
}

// This function evaluates an expression (currently only supports basic operations)
static int evaluate_expression(ASTNode *node)
{

    if (!node)
    {
        return 0;
    }

    // Handle type casting
    if (node->type == NODE_TYPE_CAST)
    {

        if (strcmp(node->target_type, "int") == 0)
        {
            if (node->left->type == NODE_STRING_LITERAL)
            {
                return atoi(node->left->value);
            }
            else if (node->left->type == NODE_FLOAT_LITERAL)
            {
                return (int)atof(node->left->value);
            }
            else if (node->left->type == NODE_LITERAL)
            {
                Variable *var = get_variable(node->left->value);
                if (var)
                {
                    switch (var->type)
                    {
                    case FLOAT_TYPE:
                        return (int)var->value.float_value;
                    case STRING_TYPE:
                        return atoi(var->value.string_value);
                    case INT_TYPE:
                        return var->value.int_value;
                    case BOOL_TYPE:
                        return var->value.bool_value ? 1 : 0;
                    default:
                        printf("[ERROR] Unsupported variable type for int cast\n");
                        return 0;
                    }
                }
            }
        }
        else if (strcmp(node->target_type, "float") == 0)
        {
            // For float casts, delegate to evaluate_float_expression
            return (int)evaluate_float_expression(node);
        }
    }

    switch (node->type)
    {
    case NODE_INT_LITERAL:
        return atoi(node->value);

    case NODE_FLOAT_LITERAL:
        return (int)atof(node->value);

    case NODE_LITERAL:
    {
        Variable *var = get_variable(node->value);
        if (!var)
        {
            printf("[ERROR] Undefined variable: %s\n", node->value);
            return 0;
        }
        // Special handling for array printing
        if (var->type == ARRAY_TYPE && var->value.array_value)
        {
            ArrayValue *array = var->value.array_value;
            printf("[");
            for (size_t i = 0; i < array->length; i++)
            {
                if (i > 0)
                    printf(", ");

                void *element = array->elements[i];
                switch (array->type)
                {
                case INT_TYPE:
                    printf("%d", *(int *)element);
                    break;
                case STRING_TYPE:
                    printf("\"%s\"", (char *)element);
                    break;
                case FLOAT_TYPE:
                    printf("%g", *(double *)element);
                    break;
                case BOOL_TYPE:
                    printf("%s", *(bool *)element ? "yup" : "nope");
                    break;
                case CHAR_TYPE:
                    printf("'%c'", *(char *)element);
                    break;
                default:
                    printf("?");
                }
            }
            printf("]");
            fflush(stdout);
            return -1;
        }

        switch (var->type)
        {
        case INT_TYPE:
            return var->value.int_value;
        case FLOAT_TYPE:
            return (int)var->value.float_value;
        case BOOL_TYPE:
            return var->value.bool_value ? 1 : 0;
        case STRING_TYPE:
            return atoi(var->value.string_value);
        default:
            printf("[ERROR] Unsupported variable type in expression\n");
            return 0;
        }
    }

    case NODE_BINARY_OP:
    {
        int left = evaluate_expression(node->left);
        int right = evaluate_expression(node->right);

        if (strcmp(node->value, "+") == 0)
            return left + right;
        if (strcmp(node->value, "-") == 0)
            return left - right;
        if (strcmp(node->value, "*") == 0)
            return left * right;
        if (strcmp(node->value, "/") == 0)
            return right != 0 ? left / right : 0;
        if (strcmp(node->value, "%") == 0)
            return right != 0 ? left % right : 0;
        if (strcmp(node->value, "**") == 0)
        {
            // For power operations, always use floating-point calculation
            ASTNode *float_node = create_node(NODE_FLOAT_LITERAL, NULL, NULL, "float");
            float_node->left = node->left;
            float_node->right = node->right;
            double result = evaluate_float_expression(float_node);
            free(float_node);
            return (int)result;  // Convert back to int if needed
        }

        return 0;
    }

    case NODE_FUNCTION_CALL:
    {
        char *result = execute_function(node->function_name, node->arguments);
        if (result)
        {
            int value = atoi(result);
            free(result);
            return value;
        }
        return 0;
    }
    // case NODE_ARRAY_LITERAL:
    // {
    //     printf("DEBUG: Evaluating array literal\n");
    //     // For array literals, evaluate each element
    //     ASTNode *current = node->elements;
    //     while (current)
    //     {
    //         printf("DEBUG: Processing array literal element\n");
    //         int value = evaluate_expression(current);
    //         printf("DEBUG: Got array element value: %d\n", value);
    //         current = current->next;
    //     }
    //     return 0; // Array literals in expressions return 0
    // }
    case NODE_ARRAY_ACCESS:
    {
        // printf("DEBUG: Evaluating array access in evaluate_expression\n");
        Variable *array_var = get_variable(node->var_name);
        if (!array_var || !array_var->value.array_value)
        {
            printf("ERROR: Array '%s' not found or uninitialized\n", node->var_name);
            return 0;
        }

        void *result = interpret_array_access(node, array_var->value.array_value);
        if (!result)
        {
            printf("ERROR: Array access failed\n");
            return 0;
        }

        // Convert the result to int
        int value = *(int *)result;
        free(result);
        return value;
    }

    default:
        printf("[ERROR] Unsupported node type in expression: %d\n", node->type);
        return 0;
    }
}

static bool evaluate_bool_expression(ASTNode *node)
{
    if (!node)
        return false;

    // Handle comparison operators that return boolean values
    if (node->type == NODE_BINARY_OP)
    {
        if (strcmp(node->value, "==") == 0 ||
            strcmp(node->value, "!=") == 0 ||
            strcmp(node->value, "<") == 0 ||
            strcmp(node->value, ">") == 0 ||
            strcmp(node->value, "<=") == 0 ||
            strcmp(node->value, ">=") == 0)
        {
            // These operators naturally return boolean results
            return evaluate_comparison(node);
        }
        else if (strcmp(node->value, "&&") == 0)
        {
            return evaluate_bool_expression(node->left) && evaluate_bool_expression(node->right);
        }
        else if (strcmp(node->value, "||") == 0)
        {
            return evaluate_bool_expression(node->left) || evaluate_bool_expression(node->right);
        }
    }

    // For direct boolean values
    if (node->type == NODE_BOOL_LITERAL)
    {
        return strcmp(node->value, "yup") == 0;
    }

    // For variables
    if (node->type == NODE_LITERAL)
    {
        Variable *var = get_variable(node->value);
        if (var && var->type == BOOL_TYPE)
        {
            return var->value.bool_value;
        }
    }

    // For numeric expressions that need to be converted to boolean
    int value = evaluate_expression(node);
    return value != 0; // Any non-zero value is considered true
}

// Helper function to evaluate comparisons
bool evaluate_comparison(ASTNode *node)
{
    if (!node || node->type != NODE_BINARY_OP)
        return false;

    int left = evaluate_expression(node->left);
    int right = evaluate_expression(node->right);

    if (strcmp(node->value, "==") == 0)
        return left == right;
    if (strcmp(node->value, "!=") == 0)
        return left != right;
    if (strcmp(node->value, "<") == 0)
        return left < right;
    if (strcmp(node->value, ">") == 0)
        return left > right;
    if (strcmp(node->value, "<=") == 0)
        return left <= right;
    if (strcmp(node->value, ">=") == 0)
        return left >= right;

    return false;
}

char *evaluate_string_expression(ASTNode *node)
{
    if (node == NULL)
        return strdup("");

    if (node->type == NODE_STRING_LITERAL)
    {
        return strdup(node->value);
    }
    else if (node->type == NODE_FUNCTION_CALL)
    {
        char *result = execute_function(node->function_name, node->arguments);
        return result ? result : strdup("");
    }
    else if (node->type == NODE_LITERAL)
    {
        Variable *var = get_variable(node->value);
        if (var && var->type == STRING_TYPE)
        {
            return strdup(var->value.string_value);
        }
        else if (var && var->type == INT_TYPE)
        {
            // Convert int to string
            char buffer[32];
            snprintf(buffer, sizeof(buffer), "%d", var->value.int_value);
            return strdup(buffer);
        }
        else if (var && var->type == FLOAT_TYPE)
        {
            // Convert float to string
            char buffer[32];
            snprintf(buffer, sizeof(buffer), "%g", var->value.float_value);
            return strdup(buffer);
        }
        else if (var && var->type == BOOL_TYPE)
        {
            // Convert bool to string
            return strdup(var->value.bool_value ? "yup" : "nope");
        }
        else if (var && var->type == CHAR_TYPE)
        {
            // Convert char to string
            char buffer[2];
            buffer[0] = var->value.char_value;
            buffer[1] = '\0';
            return strdup(buffer);
        }
        else
        {
            return strdup("");
        }
    }
    else if (node->type == NODE_BINARY_OP && strcmp(node->value, "+") == 0)
    {
        // Handle string concatenation
        char *left = evaluate_string_expression(node->left);
        char *right = evaluate_string_expression(node->right);

        // Check if right operand is a float variable or float literal
        if (node->right->type == NODE_LITERAL)
        {
            Variable *var = get_variable(node->right->value);
            if (var && var->type == FLOAT_TYPE)
            {
                double val = var->value.float_value;
                char float_str[32];
                if (val == (int)val)
                {
                    snprintf(float_str, sizeof(float_str), "%.1f", val); // Force .0 for whole numbers
                }
                else
                {
                    snprintf(float_str, sizeof(float_str), "%g", val); // Use original precision for decimals
                }
                free(right);
                right = strdup(float_str);
            }
        }
        else if (node->right->type == NODE_FLOAT_LITERAL)
        {
            double val = atof(node->right->value);
            char float_str[32];
            if (val == (int)val)
            {
                snprintf(float_str, sizeof(float_str), "%.1f", val);
            }
            else
            {
                snprintf(float_str, sizeof(float_str), "%g", val);
            }
            free(right);
            right = strdup(float_str);
        }

        // Allocate space for concatenated string
        char *result = malloc(strlen(left) + strlen(right) + 1);
        if (result)
        {
            strcpy(result, left);
            strcat(result, right);
        }

        free(left);
        free(right);

        return result ? result : strdup("");
    }
    else if (node->type == NODE_INT_LITERAL)
    {
        // Convert int literal to string
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "%d", atoi(node->value));
        return strdup(buffer);
    }
    else if (node->type == NODE_FLOAT_LITERAL)
    {
        // Convert float literal to string
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "%g", atof(node->value));
        return strdup(buffer);
    }
    else if (node->type == NODE_BOOL_LITERAL)
    {
        // Convert bool literal to string
        return strdup(strcmp(node->value, "yup") == 0 ? "yup" : "nope");
    }
    else if (node->type == NODE_CHAR_LITERAL)
    {
        // Convert char literal to string
        char buffer[2];
        buffer[0] = node->value[0];
        buffer[1] = '\0';
        return strdup(buffer);
    }
    else if (node->type == NODE_INPUT)
    {
        return evaluate_input(node->value);
    }

    return strdup("");
}

static double evaluate_float_expression(ASTNode *node)
{

    if (!node)
    {
        return 0.0;
    }

    // Handle type casting
    if (node->type == NODE_TYPE_CAST)
    {

        if (strcmp(node->target_type, "float") == 0)
        {
            switch (node->left->type)
            {
            case NODE_INT_LITERAL:
                return (double)atoi(node->left->value);
            case NODE_FLOAT_LITERAL:
                return atof(node->left->value);
            case NODE_STRING_LITERAL:
                return atof(node->left->value);
            case NODE_LITERAL:
            {
                Variable *var = get_variable(node->left->value);
                if (var)
                {
                    switch (var->type)
                    {
                    case INT_TYPE:
                        return (double)var->value.int_value;
                    case FLOAT_TYPE:
                        return var->value.float_value;
                    case STRING_TYPE:
                        return atof(var->value.string_value);
                    case BOOL_TYPE:
                        return var->value.bool_value ? 1.0 : 0.0;
                    default:
                        printf("[ERROR] Unsupported variable type for float cast\n");
                        return 0.0;
                    }
                }
                break;
            }
            default:
                printf("[ERROR] Unsupported node type for float cast: %d\n",
                       node->left->type);
                return 0.0;
            }
        }
    }

    // Handle regular expressions
    switch (node->type)
    {
    case NODE_FLOAT_LITERAL:
        return atof(node->value);

    case NODE_INT_LITERAL:
        return (double)atoi(node->value);

    case NODE_LITERAL:
    {
        Variable *var = get_variable(node->value);
        if (!var)
        {
            printf("[ERROR] Undefined variable: %s\n", node->value);
            return 0.0;
        }
        switch (var->type)
        {
        case FLOAT_TYPE:
            return var->value.float_value;
        case INT_TYPE:
            return (double)var->value.int_value;
        case STRING_TYPE:
            return atof(var->value.string_value);
        case BOOL_TYPE:
            return var->value.bool_value ? 1.0 : 0.0;
        default:
            printf("[ERROR] Unsupported variable type in float expression\n");
            return 0.0;
        }
    }

    case NODE_BINARY_OP:
    {
        double left = evaluate_float_expression(node->left);
        double right = evaluate_float_expression(node->right);

        if (strcmp(node->value, "+") == 0)
            return left + right;
        if (strcmp(node->value, "-") == 0)
            return left - right;
        if (strcmp(node->value, "*") == 0)
            return left * right;
        if (strcmp(node->value, "/") == 0)
            return right != 0.0 ? left / right : 0.0;
        if (strcmp(node->value, "**") == 0)
        {
            // Handle special case: 0 raised to negative power
            if (left == 0.0 && right < 0)
            {
                printf("\033[1;31mERROR:\033[0m Sorry Bro, can't raise 0 to a negative power — math says nope!\n");
                exit(1);  // Exit with error status
            }
            
            // For negative exponents, calculate positive power first then take reciprocal
            if (right < 0)
            {
                double positive_power = pow(left, -right);
                if (positive_power == 0.0)
                {
                    printf("\033[1;31mERROR:\033[0m Sorry bro, your expression has a division by 0.\n");
                    exit(1);
                }
                return 1.0 / positive_power;
            }
            
            return pow(left, right);
        }

        return 0.0;
    }

    default:
        printf("[ERROR] Unsupported node type in float expression: %d\n", node->type);
        return 0.0;
    }
}

static bool can_implicitly_convert(VariableType from_type, VariableType to_type)
{
    switch (to_type)
    {
    case FLOAT_TYPE:
        return from_type == INT_TYPE || from_type == CHAR_TYPE;
    case INT_TYPE:
        return from_type == CHAR_TYPE || from_type == BOOL_TYPE;
    case STRING_TYPE:
        return false; // No implicit conversion to string
    case CHAR_TYPE:
        return false; // No implicit conversion to char
    case BOOL_TYPE:
        return false; // No implicit conversion to bool
    default:
        return false;
    }
}

static const char *type_to_string(VariableType type)
{
    switch (type)
    {
    case INT_TYPE:
        return "int";
    case FLOAT_TYPE:
        return "float";
    case STRING_TYPE:
        return "string";
    case BOOL_TYPE:
        return "boolean";
    case CHAR_TYPE:
        return "char";
    default:
        return "unknown";
    }
}

static char *evaluate_input(const char *prompt)
{
    printf("%s", prompt);

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    read = getline(&line, &len, stdin);

    if (read == -1)
    {
        free(line);
        return strdup("");
    }

    if (read > 0 && line[read - 1] == '\n')
    {
        line[read - 1] = '\0';
        read--;
    }

    char *result = malloc(read + 1);
    if (!result) {
        free(line);
        return strdup("");
    }

    memcpy(result, line, read);
    result[read] = '\0';
    
    free(line);
    return result;
}

