void print_array_element(void *element, VariableType type)
{
    if (!element)
    {
        printf("null");
        return;
    }

    switch (type)
    {
    case INT_TYPE:
        printf("%d\n", *(int *)element);
        break;
    case FLOAT_TYPE:
        printf("%g\n", *(double *)element);
        break;
    case STRING_TYPE:
        printf("%s\n", (char *)element);
        break;
    case BOOL_TYPE:
        printf("%s\n", *(bool *)element ? "yup" : "nope");
        break;
    default:
        printf("Error: Unsupported type %d", type);
    }
}


// This is the main function that interprets our AST
void interpret(ASTNode *node)
{
    // Register built-in functions if not already done
    register_builtin_functions();

    while (node)
    {
        // printf("DEBUG: Interpreting node type: %d\n", node->type);

        switch (node->type)
        {
        case NODE_FUNCTION_CALL:
        {
            // Only execute the function, don't print the result
            char *result = execute_function(node->function_name, node->arguments);
            if (result)
            {
                free(result);
            }
            break;
        }
        case NODE_ARRAY_DECLARATION:
        {
            // printf("DEBUG: Handling array declaration for '%s'\n", node->var_name);
            ArrayValue *array = (ArrayValue *)interpret_array_declaration(node);
            if (array)
            {
                // printf("DEBUG: Processing array elements for '%s'\n", node->var_name);

                // Process each element in the array literal
                ASTNode *current = node->elements;
                if (current && current->type == NODE_ARRAY_LITERAL)
                {
                    // printf("DEBUG: Processing array literal elements\n");
                    ASTNode *element = current->elements;
                    while (element)
                    {
                        // printf("DEBUG: Processing element node type: %d\n", element->type);
                        switch (array->type)
                        {
                        case INT_TYPE:
                        {
                            int value = evaluate_expression(element);
                            int *element_value = malloc(sizeof(int));
                            *element_value = value;
                            array_add_last(array, element_value);
                            // printf("DEBUG: Added int element: %d\n", value);
                            break;
                        }
                        case STRING_TYPE:
                        {
                            if (element->type == NODE_STRING_LITERAL)
                            {
                                char *str_value = strdup(element->value);
                                array_add_last(array, str_value);
                                // printf("DEBUG: Added string element: %s\n", str_value);
                            }
                            break;
                        }
                        case EMPTY_TYPE:
                        { // For mixed/any type arrays
                            void *value = NULL;
                            switch (element->type)
                            {
                            case NODE_INT_LITERAL:
                            {
                                int *int_val = malloc(sizeof(int));
                                *int_val = atoi(element->value);
                                value = int_val;
                                break;
                            }
                            case NODE_STRING_LITERAL:
                            {
                                value = strdup(element->value);
                                break;
                            }
                            case NODE_BOOL_LITERAL:
                            {
                                bool *bool_val = malloc(sizeof(bool));
                                *bool_val = strcmp(element->value, "true") == 0;
                                value = bool_val;
                                break;
                            }
                            }
                            if (value)
                            {
                                array_add_last(array, value);
                                // printf("DEBUG: Added mixed type element\n");
                            }
                            break;
                        }
                        case FLOAT_TYPE:
                        {
                            if (element->type == NODE_FLOAT_LITERAL)
                            {
                                double value = atof(element->value);
                                double *element_value = malloc(sizeof(double));
                                *element_value = value;
                                array_add_last(array, element_value);
                                // printf("DEBUG: Added float element: %f\n", value);
                            }
                            break;
                        }
                        case BOOL_TYPE:
                        {
                            if (element->type == NODE_BOOL_LITERAL)
                            {
                                bool *element_value = malloc(sizeof(bool));
                                *element_value = strcmp(element->value, "yup") == 0;
                                array_add_last(array, element_value);
                                // printf("DEBUG: Added bool element: %s\n", element->value);
                            }
                            break;
                        }
                        }
                        element = element->next;
                    }
                }

                // printf("DEBUG: Final array length: %zu\n", array->length);
                set_variable(node->var_name, ARRAY_TYPE, array);
            }
            break;
        }
        case NODE_ARRAY_METHOD_CALL:
        {
            // DEBUG_LOG("Interpreting array method call");
            if (!node || !node->var_name)
            {
                // DEBUG_LOG("Invalid array method call node");
                break;
            }

            Variable *array_var = get_variable(node->var_name);
            if (!array_var)
            {
                printf("Error: Array '%s' not found\n", node->var_name);
                break;
            }

            if (array_var->type != ARRAY_TYPE || !array_var->value.array_value)
            {
                printf("Error: '%s' is not a valid array\n", node->var_name);
                break;
            }

            // DEBUG_LOG("Found array '%s', executing method '%s'",
            //           node->var_name, node->method_name);

            void *result = interpret_array_method_call(node, array_var->value.array_value);
            if (result)
            {
                // Handle the result if needed (for methods that return values)
                free(result);
            }
            break;
        }
        case NODE_PRINT:
        {
            if (node->left->type == NODE_FUNCTION_CALL)
            {
                Function *func = find_function(node->left->function_name);
                if (!func)
                {
                    printf("Error: Undefined function '%s'\n", node->left->function_name);
                    exit(1);
                }

                char *result = execute_function(node->left->function_name, node->left->arguments);
                if (result)
                {
                    printf("%s\n", result);
                    free(result);
                }
            }
            else if (node->left->type == NODE_BINARY_OP && strcmp(node->left->value, "**") == 0)
            {
                // Always handle power operations as floating point
                double result = evaluate_float_expression(node->left);
                printf("%g\n", result);
            }
            else if (node->left->type == NODE_FLOAT_LITERAL ||
                     (node->left->type == NODE_LITERAL && get_variable(node->left->value)->type == FLOAT_TYPE))
            {
                double result = evaluate_float_expression(node->left);
                 // Check if the number is a whole number
                if (result == (int)result)
                {
                    printf("%.1f\n", result); // Force .0 for whole numbers
                }
                else
                {
                    printf("%g\n", result); // Use original precision for decimals
                }
                // printf("%g\n", result);
            }
            else if (node->left->type == NODE_BOOL_LITERAL ||
                     (node->left->type == NODE_LITERAL && get_variable(node->left->value)->type == BOOL_TYPE))
            {
                bool result = evaluate_bool_expression(node->left);
                printf("%s\n", result ? "yup" : "nope");
            }
            else if (node->left->type == NODE_CHAR_LITERAL ||
                     (node->left->type == NODE_LITERAL && get_variable(node->left->value)->type == CHAR_TYPE))
            {
                char result = evaluate_expression(node->left);
                printf("%c\n", result);
            }
            else if (node->left->type == NODE_BINARY_OP)
            {
                // Check if any operand is a float
                bool has_float = false;
                if (node->left->left && (node->left->left->type == NODE_FLOAT_LITERAL ||
                                         (node->left->left->type == NODE_LITERAL &&
                                          get_variable(node->left->left->value) &&
                                          get_variable(node->left->left->value)->type == FLOAT_TYPE)))
                {
                    has_float = true;
                }
                if (node->left->right && (node->left->right->type == NODE_FLOAT_LITERAL ||
                                          (node->left->right->type == NODE_LITERAL &&
                                           get_variable(node->left->right->value) &&
                                           get_variable(node->left->right->value)->type == FLOAT_TYPE)))
                {
                    has_float = true;
                }

                // Check if it's a string concatenation operation
                if (node->left->value && strcmp(node->left->value, "+") == 0 &&
                    (node->left->left->type == NODE_STRING_LITERAL ||
                     node->left->right->type == NODE_STRING_LITERAL ||
                     (node->left->left->type == NODE_LITERAL &&
                      get_variable(node->left->left->value)->type == STRING_TYPE) ||
                     (node->left->right->type == NODE_LITERAL &&
                      get_variable(node->left->right->value)->type == STRING_TYPE)))
                {
                    char *result = evaluate_string_expression(node->left);
                    printf("%s\n", result);
                    free(result);
                }
                // Keep existing boolean expression handling
                else if (node->left->value && (strcmp(node->left->value, "==") == 0 ||
                                               strcmp(node->left->value, "!=") == 0 ||
                                               strcmp(node->left->value, ">") == 0 ||
                                               strcmp(node->left->value, "<") == 0 ||
                                               strcmp(node->left->value, ">=") == 0 ||
                                               strcmp(node->left->value, "<=") == 0 ||
                                               strcmp(node->left->value, "&&") == 0 ||
                                               strcmp(node->left->value, "||") == 0 ||
                                               strcmp(node->left->value, "!") == 0))
                {
                    bool result = evaluate_bool_expression(node->left);
                    printf("%s\n", result ? "yup" : "nope");
                }
                else if (has_float)
                {
                    double result = evaluate_float_expression(node->left);
                    printf("%g\n", result);
                }
                else
                {
                    int result = evaluate_expression(node->left);
                    printf("%d\n", result);
                }
            }
            else if (node->left->type == NODE_STRING_LITERAL ||
                     (node->left->type == NODE_LITERAL && get_variable(node->left->value)->type == STRING_TYPE))
            {
                char *result = evaluate_string_expression(node->left);
                printf("%s\n", result);
                free(result);
            }
            else if (node->left->type == NODE_ARRAY_ACCESS)
            {
                // Get the array variable
                Variable *array_var = get_variable(node->left->var_name);
                if (!array_var || !array_var->value.array_value)
                {
                    printf("Error: Invalid array access\n");
                    return;
                }

                // Get the array element
                void *result = interpret_array_access(node->left, array_var->value.array_value);
                if (result)
                {
                    print_array_element(result, array_var->value.array_value->type);
                    free(result); // Free the copied result
                }
            }
            else
            {
                int result = evaluate_expression(node->left);
                if (result != (void *)-1)
                {
                    printf("%d\n", result);
                }
            }
            break;
        }
        case NODE_ASSIGNMENT:
            handle_assignment(node);
            break;
        case NODE_IF:
        {
            bool condition = evaluate_bool_expression(node->left);

            if (condition)
            {
                interpret(node->right);
            }
            else if (node->else_branch)
            {
                interpret(node->else_branch);
            }
            break;
        }
        case NODE_TERNARY:
        {
            bool condition = evaluate_bool_expression(node->left);
            if (condition)
            {
                interpret(node->right); // true expression
            }
            else if (node->else_branch)
            {
                interpret(node->else_branch); // false expression
            }
            break;
        }
        case NODE_FOR:
        {
            // Execute initialisation
            interpret(node->init);

            // Save variable count before loop
            int saved_var_count = variable_count;
            int loop_var_count = variable_count;

            // Loop while condition is true
            while (evaluate_bool_expression(node->condition))
            {
                // Execute body
                interpret(node->body);

                // Execute increment
                interpret(node->increment);

                // Restore loop variables to their state after initialization
                // but keep any variables created inside the loop
                for (int i = saved_var_count; i < loop_var_count; i++)
                {
                    Variable *var = &variables[i];
                    // Find the original variable
                    for (int j = loop_var_count; j < variable_count; j++)
                    {
                        if (strcmp(variables[j].name, var->name) == 0)
                        {
                            // Copy the value back
                            if (var->type == INT_TYPE)
                            {
                                var->value.int_value = variables[j].value.int_value;
                            }
                            else if (var->type == FLOAT_TYPE)
                            {
                                var->value.float_value = variables[j].value.float_value;
                            }
                            else if (var->type == BOOL_TYPE)
                            {
                                var->value.bool_value = variables[j].value.bool_value;
                            }
                            else if (var->type == CHAR_TYPE)
                            {
                                var->value.char_value = variables[j].value.char_value;
                            }
                            else if (var->type == STRING_TYPE)
                            {
                                free(var->value.string_value);
                                var->value.string_value = strdup(variables[j].value.string_value);
                            }
                            break;
                        }
                    }
                }

                // Clean up variables created inside the loop
                while (variable_count > loop_var_count)
                {
                    variable_count--;
                    free(variables[variable_count].name);
                    if (variables[variable_count].type == STRING_TYPE)
                    {
                        free(variables[variable_count].value.string_value);
                    }
                }
            }

            // Restore variable count after loop (clean up loop scope)
            while (variable_count > saved_var_count)
            {
                variable_count--;
                free(variables[variable_count].name);
                if (variables[variable_count].type == STRING_TYPE)
                {
                    free(variables[variable_count].value.string_value);
                }
            }
            break;
        }
        case NODE_FUNCTION_DEFINITION:
            register_function(node->function_name, node->return_type, node->parameters, node->body);
            break;

        case NODE_VAR_DECLARATION:
        {
            // printf("DEBUG: Interpreting var declaration for '%s' of type '%s'\n",
                //    node->var_name, node->var_type);
            if (node->left && node->left->type == NODE_TYPE_CAST)
            {
                // Handle type cast in variable declaration
                if (strcmp(node->var_type, "string") == 0)
                {
                    char buffer[256];
                    switch (node->left->left->type)
                    {
                    case NODE_INT_LITERAL:
                    case NODE_LITERAL:
                        snprintf(buffer, sizeof(buffer), "%s", node->left->left->value);
                        break;
                    case NODE_FLOAT_LITERAL:
                        snprintf(buffer, sizeof(buffer), "%.2f", atof(node->left->left->value));
                        break;
                    case NODE_BOOL_LITERAL:
                        snprintf(buffer, sizeof(buffer), "%s",
                                 strcmp(node->left->left->value, "yup") == 0 ? "yup" : "nope");
                        break;
                    case NODE_STRING_LITERAL:
                        strncpy(buffer, node->left->left->value, sizeof(buffer) - 1);
                        buffer[sizeof(buffer) - 1] = '\0';
                        break;
                    case NODE_INPUT:
                    {
                        printf("%s", node->left->left->value);
                        fflush(stdout);
                        if (fgets(buffer, sizeof(buffer), stdin))
                        {
                            buffer[strcspn(buffer, "\n")] = 0;
                        }
                        break;
                    }
                    default:
                        snprintf(buffer, sizeof(buffer), "%s", node->left->left->value);
                        break;
                    }
                    set_variable(node->var_name, STRING_TYPE, buffer);
                }
                else if (strcmp(node->var_type, "float") == 0)
                {
                    double value = 0.0;
                    switch (node->left->left->type)
                    {
                    case NODE_STRING_LITERAL:
                        value = atof(node->left->left->value);
                        break;
                    case NODE_INPUT:
                    {
                        char input[256];
                        printf("%s", node->left->left->value);
                        fflush(stdout);
                        if (fgets(input, sizeof(input), stdin))
                        {
                            input[strcspn(input, "\n")] = 0;
                            value = atof(input);
                        }
                        break;
                    }
                    case NODE_INT_LITERAL:
                        value = (double)atoi(node->left->left->value);
                        break;
                    case NODE_FLOAT_LITERAL:
                        value = atof(node->left->left->value);
                        break;
                    case NODE_BOOL_LITERAL:
                        value = (strcmp(node->left->left->value, "yup") == 0) ? 1.0 : 0.0;
                        break;
                    default:
                        printf("Error: Cannot convert type to float\n");
                        exit(1);
                    }
                    set_variable(node->var_name, FLOAT_TYPE, &value);
                }
                else if (strcmp(node->var_type, "boolean") == 0)
                {
                    bool value = false;
                    switch (node->left->left->type)
                    {
                    case NODE_INT_LITERAL:
                        value = atoi(node->left->left->value) != 0;
                        break;
                    case NODE_FLOAT_LITERAL:
                        value = atof(node->left->left->value) != 0.0;
                        break;
                    case NODE_STRING_LITERAL:
                        value = strlen(node->left->left->value) > 0 &&
                                strcmp(node->left->left->value, "nope") != 0 &&
                                strcmp(node->left->left->value, "0") != 0;
                        break;
                    case NODE_BOOL_LITERAL:
                        value = strcmp(node->left->left->value, "yup") == 0;
                        break;
                    case NODE_INPUT:
                    {
                        char input[256];
                        printf("%s", node->left->left->value);
                        fflush(stdout);
                        if (fgets(input, sizeof(input), stdin))
                        {
                            input[strcspn(input, "\n")] = 0;
                            value = strlen(input) > 0 &&
                                    strcmp(input, "nope") != 0 &&
                                    strcmp(input, "0") != 0;
                        }
                        break;
                    }
                    default:
                        printf("Error: Cannot convert type to boolean\n");
                        exit(1);
                    }
                    // Convert bool to yup/nope
                    char *bool_str = value ? "yup" : "nope";
                    set_variable(node->var_name, BOOL_TYPE, bool_str);
                }
                else if (strcmp(node->var_type, "int") == 0)
                {
                    int value = 0;
                    switch (node->left->left->type)
                    {
                    case NODE_STRING_LITERAL:
                        value = atoi(node->left->left->value);
                        break;
                    case NODE_INPUT:
                    {
                        char input[256];
                        printf("%s", node->left->left->value);
                        fflush(stdout);
                        if (fgets(input, sizeof(input), stdin))
                        {
                            input[strcspn(input, "\n")] = 0;
                            value = atoi(input);
                        }
                        break;
                    }
                    case NODE_FLOAT_LITERAL:
                        value = (int)atof(node->left->left->value);
                        break;
                    case NODE_INT_LITERAL:
                        value = atoi(node->left->left->value);
                        break;
                    case NODE_BOOL_LITERAL:
                        value = (strcmp(node->left->left->value, "yup") == 0) ? 1 : 0;
                        break;
                    default:
                        printf("Error: Cannot convert type to int\n");
                        exit(1);
                    }
                    set_variable(node->var_name, INT_TYPE, &value);
                }
                else if (strcmp(node->var_type, "float") == 0)
                {
                    float value = 0.0f;
                    switch (node->left->left->type)
                    {
                    case NODE_STRING_LITERAL:
                        value = atof(node->left->left->value);
                        break;
                    case NODE_INPUT:
                    {
                        char input[256];
                        printf("%s", node->left->left->value);
                        fflush(stdout);
                        if (fgets(input, sizeof(input), stdin))
                        {
                            input[strcspn(input, "\n")] = 0;
                            value = atof(input);
                        }
                        break;
                    }
                    case NODE_INT_LITERAL:
                        value = (float)atoi(node->left->left->value);
                        break;
                    case NODE_FLOAT_LITERAL:
                        value = atof(node->left->left->value);
                        break;
                    case NODE_BOOL_LITERAL:
                        value = (strcmp(node->left->left->value, "true") == 0) ? 1.0f : 0.0f;
                        break;
                    default:
                        printf("Error: Cannot convert type to float\n");
                        exit(1);
                    }
                    set_variable(node->var_name, FLOAT_TYPE, &value);
                }
                else if (strcmp(node->var_type, "boolean") == 0)
                {
                    bool value = node->left ? evaluate_bool_expression(node->left) : false;
                    set_variable(node->var_name, BOOL_TYPE, &value);
                }
                else if (strcmp(node->var_type, "string") == 0)
                {
                    if (node->left->type == NODE_INPUT)
                    {
                        // Handle input function specially
                        char *value = evaluate_input(node->left->value);
                        set_variable(node->var_name, STRING_TYPE, value);
                        free(value);
                    }
                    else if (node->left->type != NODE_STRING_LITERAL &&
                             !(node->left->type == NODE_LITERAL &&
                               get_variable(node->left->value)->type == STRING_TYPE) &&
                             !(node->left->type == NODE_BINARY_OP && strcmp(node->left->value, "+") == 0))
                    {
                        printf("Error: Type mismatch - Cannot convert to string for variable '%s'. Use string concatenation (+) for conversion.\n",
                               node->var_name);
                        exit(1);
                    }
                    else
                    {
                        char *value = evaluate_string_expression(node->left);
                        set_variable(node->var_name, STRING_TYPE, value);
                        free(value);
                    }
                }
                else if (strcmp(node->var_type, "char") == 0)
                {
                    char value = node->left->value[0];
                    set_variable(node->var_name, CHAR_TYPE, &value);
                }
                else if (strstr(node->var_type, "<"))
                {
                    // Array declaration
                    // printf("DEBUG: Found array declaration\n");

                    // printf("DEBUG: Processing array declaration\n");
                    char *array_type = extract_array_type(node->var_type);
                    // printf("DEBUG: Array type extracted: %s\n", array_type);

                    void *array_value = interpret_array_declaration(node);
                    // printf("DEBUG: Array initialization returned: %p\n", array_value);

                    if (array_value)
                    {
                        // printf("DEBUG: About to set array variable '%s'\n", node->var_name);

                        set_variable(node->var_name, ARRAY_TYPE, array_value);
                        // printf("DEBUG: Array variable '%s' set in variable table\n", node->var_name);
                    }
                    else
                    {
                        printf("ERROR: Failed to initialize array\n");
                    }
                    free(array_type);
                }
                break;
            }
            else
            {
                if (node->left && node->left->type == NODE_FUNCTION_CALL)
                {
                    Function *func = find_function(node->left->function_name);
                    if (!func)
                    {
                        printf("Error: Undefined function '%s'\n", node->left->function_name);
                        exit(1);
                    }

                    // Get function's return type
                    VariableType func_return_type = get_function_return_type(func->return_type);

                    // Check if return type is compatible with variable type
                    if (func_return_type != get_type_from_string(node->var_type) && !can_implicitly_convert(func_return_type, get_type_from_string(node->var_type)))
                    {
                        printf("Error: Type mismatch - Cannot assign return value of function '%s' (%s) to variable '%s' (%s)\n",
                               node->left->function_name, type_to_string(func_return_type),
                               node->var_name, type_to_string(get_type_from_string(node->var_type)));
                        exit(1);
                    }

                    char *result = execute_function(node->left->function_name, node->left->arguments);
                    if (result)
                    {
                        if (strcmp(node->var_type, "string") == 0)
                        {
                            set_variable(node->var_name, STRING_TYPE, result);
                        }
                        else if (strcmp(node->var_type, "int") == 0)
                        {
                            int value = atoi(result);
                            set_variable(node->var_name, INT_TYPE, &value);
                        }
                        else if (strcmp(node->var_type, "float") == 0)
                        {
                            double value = atof(result);
                            set_variable(node->var_name, FLOAT_TYPE, &value);
                        }
                        else if (strcmp(node->var_type, "boolean") == 0)
                        {
                            bool value = strtobool(result);
                            set_variable(node->var_name, BOOL_TYPE, &value);
                        }
                        else if (strcmp(node->var_type, "char") == 0)
                        {
                            char value = result[0];
                            set_variable(node->var_name, CHAR_TYPE, &value);
                        }
                        free(result);
                    }
                }
                else if (strcmp(node->var_type, "float") == 0)
                {
                    VariableType expr_type;

                    // Determine expression type
                    if (node->left->type == NODE_STRING_LITERAL)
                    {
                        expr_type = STRING_TYPE;
                    }
                    else if (node->left->type == NODE_FLOAT_LITERAL)
                    {
                        expr_type = FLOAT_TYPE;
                    }
                    else if (node->left->type == NODE_BOOL_LITERAL)
                    {
                        expr_type = BOOL_TYPE;
                    }
                    else if (node->left->type == NODE_CHAR_LITERAL)
                    {
                        expr_type = CHAR_TYPE;
                    }
                    else if (node->left->type == NODE_LITERAL && get_variable(node->left->value))
                    {
                        expr_type = get_variable(node->left->value)->type;
                    }
                    else
                    {
                        expr_type = INT_TYPE; // Default for numeric expressions
                    }

                    // Check type compatibility
                    if (expr_type != FLOAT_TYPE && !can_implicitly_convert(expr_type, FLOAT_TYPE))
                    {
                        printf("Error: Type mismatch - Cannot convert from '%s' to 'float' for variable '%s'\n",
                               type_to_string(expr_type), node->var_name);
                        exit(1);
                    }

                    // Handle the conversion
                    if (expr_type == INT_TYPE)
                    {
                        int int_val = evaluate_expression(node->left);
                        double value = (double)int_val;
                        set_variable(node->var_name, FLOAT_TYPE, &value);
                    }
                    else
                    {
                        double value = evaluate_float_expression(node->left);
                        set_variable(node->var_name, FLOAT_TYPE, &value);
                    }
                }
                else if (strcmp(node->var_type, "int") == 0)
                {
                    VariableType expr_type;

                    // Determine expression type
                    if (node->left->type == NODE_STRING_LITERAL)
                    {
                        expr_type = STRING_TYPE;
                    }
                    else if (node->left->type == NODE_FLOAT_LITERAL)
                    {
                        expr_type = FLOAT_TYPE;
                    }
                    else if (node->left->type == NODE_BOOL_LITERAL)
                    {
                        expr_type = BOOL_TYPE;
                    }
                    else if (node->left->type == NODE_CHAR_LITERAL)
                    {
                        expr_type = CHAR_TYPE;
                    }
                    else if (node->left->type == NODE_LITERAL && get_variable(node->left->value))
                    {
                        expr_type = get_variable(node->left->value)->type;
                    }
                    else
                    {
                        expr_type = INT_TYPE; // Default for numeric expressions
                    }

                    // Check type compatibility
                    if (expr_type != INT_TYPE && !can_implicitly_convert(expr_type, INT_TYPE))
                    {
                        printf("Error: Type mismatch - Cannot convert from '%s' to 'int' for variable '%s'\n",
                               type_to_string(expr_type), node->var_name);
                        exit(1);
                    }

                    // Handle the conversion
                    if (expr_type == BOOL_TYPE)
                    {
                        bool bool_val = evaluate_bool_expression(node->left);
                        int value = bool_val ? 1 : 0;
                        set_variable(node->var_name, INT_TYPE, &value);
                    }
                    else if (expr_type == CHAR_TYPE)
                    {
                        char char_val = node->left->value[0];
                        int value = (int)char_val;
                        set_variable(node->var_name, INT_TYPE, &value);
                    }
                    else
                    {
                        int value = evaluate_expression(node->left);
                        set_variable(node->var_name, INT_TYPE, &value);
                    }
                }
                else if (strcmp(node->var_type, "boolean") == 0)
                {
                    bool value = node->left ? evaluate_bool_expression(node->left) : false;
                    set_variable(node->var_name, BOOL_TYPE, &value);
                }
                else if (strcmp(node->var_type, "string") == 0)
                {
                    if (node->left->type == NODE_INPUT)
                    {
                        // Handle input function specially
                        char *value = evaluate_input(node->left->value);
                        set_variable(node->var_name, STRING_TYPE, value);
                        free(value);
                    }
                    else if (node->left->type != NODE_STRING_LITERAL &&
                             !(node->left->type == NODE_LITERAL &&
                               get_variable(node->left->value)->type == STRING_TYPE) &&
                             !(node->left->type == NODE_BINARY_OP && strcmp(node->left->value, "+") == 0))
                    {
                        printf("Error: Type mismatch - Cannot convert to string for variable '%s'. Use string concatenation (+) for conversion.\n",
                               node->var_name);
                        exit(1);
                    }
                    else
                    {
                        char *value = evaluate_string_expression(node->left);
                        set_variable(node->var_name, STRING_TYPE, value);
                        free(value);
                    }
                }
                else if (strcmp(node->var_type, "char") == 0)
                {
                    char value = node->left ? node->left->value[0] : '\0';
                    set_variable(node->var_name, CHAR_TYPE, &value);
                }
                break;
            }
        }
        case NODE_TYPE_CAST:
            handle_type_cast(node);
            break;
        case NODE_COMPOUND_ASSIGN:
        {
            Variable *var = get_variable(node->var_name);
            if (!var)
            {
                printf("Error: Undefined variable '%s'\n", node->var_name);
                exit(1);
            }

            if (var->type == STRING_TYPE)
            {
                // Handle string concatenation
                char *right_val = evaluate_string_expression(node->right);
                if (!right_val)
                    return;

                // Calculate new size needed
                size_t new_size = strlen(var->value.string_value) + strlen(right_val) + 1;

                // Reallocate memory for the expanded string
                char *new_str = realloc(var->value.string_value, new_size);
                if (!new_str)
                {
                    printf("Error: Memory allocation failed\n");
                    free(right_val);
                    return;
                }

                // Update the variable's string value
                var->value.string_value = new_str;
                strcat(var->value.string_value, right_val);
                free(right_val);
            }
            // if we need to handle othr types, we can do it here
            break;
        }
        case NODE_ARRAY_ACCESS:
        {
            // printf("DEBUG: Handling NODE_ARRAY_ACCESS in interpret()\n");
            Variable *array_var = get_variable(node->var_name);
            if (!array_var || !array_var->value.array_value)
            {
                printf("ERROR: Array '%s' not found or uninitialized\n", node->var_name);
                return;
            }
            void *result = interpret_array_access(node, array_var->value.array_value);
            if (!result)
            {
                printf("ERROR: Array access failed\n");
            }
            break;
        }
        default:
            break;
        }
        node = node->next;
    }
}

// Add type conversion validation and execution
static void handle_type_cast(ASTNode *node)
{
    if (!node->target_type || !node->left)
    {
        return;
    }

    // Handle casting to int
    if (strcmp(node->target_type, "int") == 0)
    {
        int value = 0;

        if (node->left->type == NODE_STRING_LITERAL)
        {
            value = atoi(node->left->value);
            set_variable(node->var_name, INT_TYPE, &value);
        }
        else
        {
            printf("Error: Unhandled node type: %d\n", node->left->type);
        }
    }

    // Handle casting to boolean
    if (strcmp(node->target_type, "boolean") == 0)
    {
        int value;

        // Get the integer value regardless of source type
        if (node->left->type == NODE_INT_LITERAL)
        {
            value = atoi(node->left->value);
        }
        else if (node->left->type == NODE_FLOAT_LITERAL)
        {
            value = (int)atof(node->left->value);
        }
        else if (node->left->type == NODE_LITERAL)
        {
            Variable *var = get_variable(node->left->value);
            if (var)
            {
                if (var->type == INT_TYPE)
                {
                    value = var->value.int_value;
                }
                else if (var->type == FLOAT_TYPE)
                {
                    value = (int)var->value.float_value;
                }
                else
                {
                    printf("Error: Cannot cast type to boolean\n");
                    exit(1);
                }
            }
        }
        else
        {
            value = evaluate_expression(node->left);
        }

        // Strict validation for boolean conversion
        if (value != 0 && value != 1)
        {
            printf("Error: Cannot cast %d to boolean. Only 0 and 1 are valid values.\n", value);
            exit(1);
        }

        bool bool_value = (value == 1);
        set_variable(node->var_name, BOOL_TYPE, &bool_value);
        return;
    }
}

static void handle_assignment(ASTNode *node)
{
    if (!node->var_name)
    {
        printf("Error: Invalid assignment - missing variable name\n");
        exit(1);
    }

    // Check if variable exists
    Variable *existing_var = get_variable(node->var_name);
    if (!existing_var)
    {
        printf("Error: Variable '%s' not declared\n", node->var_name);
        exit(1);
    }

    // Check if variable is fixed (constant)
    if (existing_var->is_fixed)
    {
        printf("Error: Cannot reassign fixed variable '%s'\n", node->var_name);
        exit(1);
    }

    // Handle array assignment
    if (node->array_access)
    {
        if (existing_var->type != ARRAY_TYPE)
        {
            printf("Error: Cannot perform array access on non-array variable '%s'\n", node->var_name);
            exit(1);
        }

        ArrayValue *array = existing_var->value.array_value;
        int index = evaluate_expression(node->array_access->index);
        
        if (index < 0 || index >= array->length)
        {
            printf("Error: Array index %d out of bounds for array '%s' (length: %d)\n", 
                   index, node->var_name, array->length);
            exit(1);
        }

        // Get the value to assign
        void *value = NULL;
        switch (array->type)
        {
            case INT_TYPE:
            {
                int val = evaluate_expression(node->left);
                value = malloc(sizeof(int));
                *(int*)value = val;
                break;
            }
            case FLOAT_TYPE:
            {
                double val = evaluate_float_expression(node->left);
                value = malloc(sizeof(double));
                *(double*)value = val;
                break;
            }
            case STRING_TYPE:
            {
                char *val = evaluate_string_expression(node->left);
                value = strdup(val);
                free(val);
                break;
            }
            case BOOL_TYPE:
            {
                bool val = evaluate_bool_expression(node->left);
                value = malloc(sizeof(bool));
                *(bool*)value = val;
                break;
            }
            case CHAR_TYPE:
            {
                char val = node->left->value[0];
                value = malloc(sizeof(char));
                *(char*)value = val;
                break;
            }
            default:
                printf("Error: Unsupported type for array element\n");
                exit(1);
        }

        // Free the old value if it exists
        if (array->elements[index])
        {
            free(array->elements[index]);
        }

        // Set the new value
        array->elements[index] = value;
        return;
    }

    // Handle regular variable assignment
    switch (existing_var->type)
    {
        case INT_TYPE:
        {
            int value = evaluate_expression(node->left);
            set_variable(node->var_name, INT_TYPE, &value);
            break;
        }
        case FLOAT_TYPE:
        {
            double value = evaluate_float_expression(node->left);
            set_variable(node->var_name, FLOAT_TYPE, &value);
            break;
        }
        case STRING_TYPE:
        {
            char *value = evaluate_string_expression(node->left);
            set_variable(node->var_name, STRING_TYPE, value);
            free(value);
            break;
        }
        case BOOL_TYPE:
        {
            bool value = evaluate_bool_expression(node->left);
            set_variable(node->var_name, BOOL_TYPE, &value);
            break;
        }
        case CHAR_TYPE:
        {
            char value = node->left->value[0];
            set_variable(node->var_name, CHAR_TYPE, &value);
            break;
        }
        default:
            printf("Error: Unsupported type for variable '%s'\n", node->var_name);
            exit(1);
    }
}

void *interpret_expression(ASTNode *node)
{
    if (!node)
    {
        return NULL;
    }

    // printf("DEBUG: Interpreting node type: %d\n", node->type);

    switch (node->type)
    {
    case NODE_BINARY_OP:
    {
        void *left_result = interpret_expression(node->left);
        void *right_result = node->right ? interpret_expression(node->right) : NULL;

        if (!left_result || (node->right && !right_result))
        {
            return NULL;
        }

        if (strcmp(node->value, "+") == 0)
        {
            // Handle addition based on types
            if (node->left->type == NODE_INT_LITERAL ||
                node->left->type == NODE_ARRAY_ACCESS)
            {
                int left_val;
                if (node->left->type == NODE_ARRAY_ACCESS)
                {
                    left_val = *(int *)left_result;
                }
                else
                {
                    left_val = *(int *)left_result;
                }

                int right_val;
                if (node->right->type == NODE_ARRAY_ACCESS)
                {
                    right_val = *(int *)right_result;
                }
                else
                {
                    right_val = *(int *)right_result;
                }

                int *result = malloc(sizeof(int));
                *result = left_val + right_val;

                free(left_result);
                free(right_result);
                return result;
            }
        }
        return NULL;
    }

    case NODE_INT_LITERAL:
    {
        int *value = malloc(sizeof(int));
        *value = atoi(node->value);
        // printf("DEBUG: Created int literal: %d\n", *value);
        return value;
    }

    case NODE_FLOAT_LITERAL:
    {
        double *value = malloc(sizeof(double));
        *value = atof(node->value);
        return value;
    }

    case NODE_STRING_LITERAL:
    {
        char *str = strdup(node->value);
        return str;
    }

    case NODE_BOOL_LITERAL:
    {
        bool *value = malloc(sizeof(bool));
        *value = (strcmp(node->value, "yup") == 0);
        return value;
    }

    case NODE_CHAR_LITERAL:
    {
        char *value = malloc(sizeof(char));
        *value = node->value[0];
        return value;
    }

    case NODE_LITERAL:
    {
        Variable *var = get_variable(node->value);
        if (!var)
        {
            return NULL;
        }
        
        // Return a copy of the variable's value based on its type
        void *value = NULL;
        switch (var->type) {
            case STRING_TYPE:
                if (var->value.string_value) {
                    value = strdup(var->value.string_value);
                }
                break;
            case INT_TYPE:
                value = malloc(sizeof(int));
                if (value) {
                    *(int*)value = var->value.int_value;
                }
                break;
            case FLOAT_TYPE:
                value = malloc(sizeof(double));
                if (value) {
                    *(double*)value = var->value.float_value;
                }
                break;
            case BOOL_TYPE:
                value = malloc(sizeof(bool));
                if (value) {
                    *(bool*)value = var->value.bool_value;
                }
                break;
        }
        return value;
    }

    case NODE_ARRAY_METHOD_CALL:
    {
        Variable *array_var = get_variable(node->var_name);
        if (!array_var)
        {
            printf("ERROR: Array '%s' not found\n", node->var_name);
            return NULL;
        }
        if (!array_var->value.array_value)
        {
            printf("ERROR: Array '%s' is not initialized\n", node->var_name);
            return NULL;
        }
        return interpret_array_method_call(node, array_var->value.array_value);
    }

    case NODE_ARRAY_ACCESS:
    {
        Variable *array_var = get_variable(node->var_name);
        if (!array_var || !array_var->value.array_value)
        {
            printf("ERROR: Array '%s' not found or uninitialized\n", node->var_name);
            return NULL;
        }

        void *result = interpret_array_access(node, array_var->value.array_value);
        if (!result)
        {
            printf("ERROR: Array access failed\n");
        }
        return result;
    }

        // case NODE_ARRAY_LITERAL:
        // {
        //     printf("DEBUG: Creating array literal\n");
        //     return interpret_array_literal(node);
        // }

    default:
        // printf("Error: Unknown expression type %d\n", node->type);
        return NULL;
    }
}

char *extract_array_type(const char *var_type)
{
    const char *start = strchr(var_type, '<');
    const char *end = strchr(var_type, '>');

    if (!start || !end || start >= end)
    {
        printf("ERROR: Invalid array type format\n");
        return NULL;
    }

    size_t type_len = end - (start + 1);
    char *array_type = malloc(type_len + 1);

    if (!array_type)
    {
        printf("ERROR: Memory allocation failed\n");
        return NULL;
    }

    strncpy(array_type, start + 1, type_len);
    array_type[type_len] = '\0';

    return array_type;
}